# Surah Yunus (chapter 10) — part 11: ayat 101-109 (IDs 1465-1473)
SURAH = 10

ENTRIES = {
1465: (
"کہدو — دیکھو — آسمانوں اور زمین — میں — کیا — کچھ — ہے — اور — آیات — اور — ڈرانے والے — فائدہ — نہیں دیتے — ایسی قوم — کو — جو ایمان نہیں لاتے",
"""۱۔ کائنات میں نشانیاں — دیکھو — آنکھیں رکھنے والوں کے لیے۔
۲۔ ’’قُلِ انظُرُوا مَاذَا فِي السَّمَاوَاتِ وَالْأَرْضِ وَمَا تُغْنِي الْآيَاتُ وَالنُّذُرُ عَن قَوْمٍ لَّا يُؤْمِنُونَ‘‘ — کہدو — دیکھو — آسمانوں اور زمین — میں — کیا — کچھ — ہے — اور — آیات — اور — ڈرانے والے — فائدہ — نہیں دیتے — ایسی قوم — کو — جو ایمان نہیں لاتے — یعنی آسمان و زمین کی نشانیاں — دیکھو — مگر آیات — ایمان لانے والوں — ہی — فائدہ دیتی ہیں۔
۳۔ عملی سبق: نشانیاں — ہر جگہ موجود ہیں؛ ایمان — لانے کا فیصلہ — آپ کا ہے۔"""
),
1466: (
"پس — وہ — ان — دنوں — جیسا — انتظار — کر رہے ہیں — جو — ان — سے پہلے — گزر چکے — کہدو — انتظار کرو — بے شک — میں — بھی — تمہارے ساتھ — منتظر — ہوں",
"""۱۔ کفار — پرانی قوموں — جیسا انجام — انتظار کر رہے ہیں۔
۲۔ ’’فَهَلْ يَنتَظِرُونَ إِلَّا مِثْلَ أَيَّامِ الَّذِينَ خَلَوْا مِن قَبْلِهِمْ قُلْ فَانتَظِرُوا إِنِّي مَعَكُم مِّنَ الْمُنتَظِرِينَ‘‘ — پس — وہ — ان — دنوں — جیسا — انتظار — کر رہے ہیں — جو — ان — سے پہلے — گزر چکے — کہدو — انتظار کرو — بے شک — میں — بھی — تمہارے ساتھ — منتظر — ہوں — یعنی وہ — پچھلی قوموں — جیسا انجام — انتظار کر رہے ہیں؛ میں بھی — تمہارے ساتھ — تمہارے — انجام — کا منتظر — ہوں۔
۳۔ عملی سبق: ظالم — کا انجام — عبرت — کا مقام ہے۔"""
),
1467: (
"پھر — ہم — اپنے رسولوں — کو — اور — ایمان لانے والوں — کو — بچائیں گے — اسی طرح — ہمارے — ذمے — ہے — کہ ہم — مؤمنوں — کو — بچائیں",
"""۱۔ اللہ کا وعدہ — رسولوں اور مؤمنوں — کی نجات۔
۲۔ ’’ثُمَّ نُنَجِّي رُسُلَنَا وَالَّذِينَ آمَنُوا كَذَٰلِكَ حَقًّا عَلَيْنَا نُنجِ الْمُؤْمِنِينَ‘‘ — پھر — ہم — اپنے رسولوں — کو — اور — ایمان لانے والوں — کو — بچائیں گے — اسی طرح — ہمارے — ذمے — ہے — کہ ہم — مؤمنوں — کو — بچائیں — یعنی اللہ — اپنے رسولوں اور مؤمنوں — کو — ضرور بچاتا ہے؛ یہ — اس کا وعدہ ہے۔
۳۔ عملی سبق: ایمان — اللہ کی حفاظت — کا ضمانت ہے۔"""
),
1468: (
"کہدو — اے — لوگو — اگر — تم — میرے دین — کے — بارے میں — شک — میں ہو — تو — میں — ان — کی عبادت نہیں کرتا — جنہیں — تم — اللہ کے سوا — پکارتے ہو — لیکن — میں — اس — اللہ کی عبادت کرتا ہوں — جو — تمہیں — وفات — دیتا ہے — اور — مجھے — حکم دیا گیا — کہ — میں مؤمنوں — میں — سے ہوں",
"""۱۔ نبیؐ — کسی شک میں نہیں — وہ صرف اللہ کی عبادت کرتے ہیں۔
۲۔ ’’قُلْ يَا أَيُّهَا النَّاسُ إِن كُنتُمْ فِي شَكٍّ مِّن دِينِي فَلَا أَعْبُدُ الَّذِينَ تَعْبُدُونَ مِن دُونِ اللَّهِ وَلَٰكِنْ أَعْبُدُ اللَّهَ الَّذِي يَتَوَفَّاكُمْ وَأُمِرْتُ أَنْ أَكُونَ مِنَ الْمُؤْمِنِينَ‘‘ — کہدو — اے — لوگو — اگر — تم — میرے دین — کے — بارے میں — شک — میں ہو — تو — میں — ان — کی عبادت نہیں کرتا — جنہیں — تم — اللہ کے سوا — پکارتے ہو — لیکن — میں — اس — اللہ کی عبادت کرتا ہوں — جو — تمہیں — وفات — دیتا ہے — اور — مجھے — حکم دیا گیا — کہ — میں مؤمنوں — میں — سے ہوں — یعنی نبیؐ — ان کی عبادت نہیں کرتے — وہ صرف اللہ — کی عبادت کرتے ہیں — جو وفات — دیتا ہے۔
۳۔ عملی سبق: شک کی صورت میں — حق کی پیروی — جاری رکھیں۔"""
),
1469: (
"اور — اپنا — چہرہ — دین — کی طرف — سیدھے طور پر — پھیر دو — اور — مشرکوں — میں — سے — نہ ہوں",
"""۱۔ دین حنیف کی طرف — سیدھا رخ۔
۲۔ ’’وَأَنْ أَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا وَلَا تَكُونَنَّ مِنَ الْمُشْرِكِينَ‘‘ — اور — اپنا — چہرہ — دین — کی طرف — سیدھے طور پر — پھیر دو — اور — مشرکوں — میں — سے — نہ ہوں — یعنی پورے دل سے — دین کی طرف — رخ کرو — مشرکوں — میں — شامل — نہ ہوں۔
۳۔ عملی سبق: خلوص — اور — یکسوئی — کے ساتھ — دین — پر استقامت کرو۔"""
),
1470: (
"اور — اللہ کے سوا — کسی — کو — نہ پکارو — جو — نہ — تجھے — فائدہ دے — اور — نہ — نقصان — پہنچائے — پس — اگر — تم نے کیا — تو پھر — بے شک — تم — ظالموں میں سے ہو",
"""۱۔ غیر اللہ کو بلانا — بے فائدہ اور ظلم۔
۲۔ ’’وَلَا تَدْعُ مِن دُونِ اللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَ فَإِن فَعَلْتَ فَإِنَّكَ إِذًا مِّنَ الظَّالِمِينَ‘‘ — اور — اللہ کے سوا — کسی — کو — نہ پکارو — جو — نہ — تجھے — فائدہ دے — اور — نہ — نقصان — پہنچائے — پس — اگر — تم نے کیا — تو پھر — بے شک — تم — ظالموں میں سے ہو — یعنی غیر اللہ کو پکارنا — بے سود — ہے اگر تم نے کیا — تو تم ظالموں میں سے ہو۔
۳۔ عملی سبق: پکارنا — صرف — اللہ کو ہے؛ وہی فائدہ اور نقصان — کا مالک ہے۔"""
),
1471: (
"اور — اگر — اللہ — تجھے — کسی — نقصان — میں — مبتلا کرے — تو — اس — کا کوئی دور کرنے والا — اس کے سوا — نہیں — اور — اگر — وہ — تجھے — کسی — خیر — کی طرف — ارادہ رکھے — تو — اس — کے فضل — کا کوئی روکنے والا — نہیں — وہ — اپنے — بندوں میں سے — جسے — چاہتا ہے — اس — کی طرف — پہنچاتا ہے — اور — وہ — بخشنے والا مہربان ہے",
"""۱۔ فائدہ اور نقصان — صرف — اللہ کے ہاتھ میں۔
۲۔ ’’وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن يُرِدْكَ بِخَيْرٍ فَلَا رَادَّ لِفَضْلِهِ يُصِيبُ بِهِ مَن يَشَاءُ مِنْ عِبَادِهِ وَهُوَ الْغَفُورُ الرَّحِيمُ‘‘ — اور — اگر — اللہ — تجھے — کسی — نقصان — میں — مبتلا کرے — تو — اس — کا کوئی دور کرنے والا — اس کے سوا — نہیں — اور — اگر — وہ — تجھے — کسی — خیر — کی طرف — ارادہ رکھے — تو — اس — کے فضل — کا کوئی روکنے والا — نہیں — وہ — اپنے — بندوں میں سے — جسے — چاہتا ہے — اس — کی طرف — پہنچاتا ہے — اور — وہ — بخشنے والا مہربان ہے — یعنی نقصان — پہنچ جائے — تو اللہ کے سوا — کوئی نہیں دور کر سکتا — اور اگر وہ — خیر — چاہے — تو کوئی نہیں روک سکتا — وہ جسے چاہے — اپنی نعمت — پہنچاتا ہے؛ وہ غفور رحیم ہے۔
۳۔ عملی سبق: تکلیف میں — اور نعمت میں — صرف اللہ — کو یاد کرو۔"""
),
1472: (
"کہدو — اے لوگو — تمہارے رب — کی طرف سے — حق — تمہارے پاس — آ چکا — پس — جو — ہدایت — پائے — تو — صرف اپنے لیے ہدایت پائی — اور — جو — گمراہ ہو — تو — صرف اپنی ذات — کے لیے — گمراہ ہوا — اور — میں — تم — پر — کوئی — نگہبان — نہیں",
"""۱۔ حق — آپؐ کے پاس پہنچ چکا — راستہ انتخاب — آپ کا ہے۔
۲۔ ’’قُلْ يَا أَيُّهَا النَّاسُ قَدْ جَاءَكُمُ الْحَقُّ مِن رَّبِّكُمْ فَمَنِ اهْتَدَىٰ فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا أَنَا عَلَيْكُم بِوَكِيلٍ‘‘ — کہدو — اے لوگو — تمہارے رب — کی طرف سے — حق — تمہارے پاس — آ چکا — پس — جو — ہدایت — پائے — تو — صرف اپنے لیے ہدایت پائی — اور — جو — گمراہ ہو — تو — صرف اپنی ذات — کے لیے — گمراہ ہوا — اور — میں — تم — پر — کوئی — نگہبان — نہیں — یعنی حق — آ چکا — جو ہدایت پائے — اپنے لیے — اور جو گمراہ — اپنے لیے؛ میں تم پر — نگہبان نہیں۔
۳۔ عملی سبق: ہدایت — آپ کا — فیصلہ ہے؛ اللہ — فیصلہ کرے گا۔"""
),
1473: (
"اور — آپ — اس — کی پیروی کرو — جو — آپؐ کی طرف — وحی کی جاتی ہے — اور — صبر — رکھو — یہاں تک کہ — اللہ — فیصلہ کرے — اور — وہ — بہترین — حاکم — ہے",
"""۱۔ نبیؐ — کو صبر کے ساتھ وحی کی پیروی کا حکم۔
۲۔ ’’وَاتَّبِعْ مَا يُوحَىٰ إِلَيْكَ وَاصْبِرْ حَتَّىٰ يَحْكُمَ اللَّهُ وَهُوَ خَيْرُ الْحَاكِمِينَ‘‘ — اور — آپ — اس — کی پیروی کرو — جو — آپؐ کی طرف — وحی کی جاتی ہے — اور — صبر — رکھو — یہاں تک کہ — اللہ — فیصلہ کرے — اور — وہ — بہترین — حاکم — ہے — یعنی وحی کی — پیروی کرو — اور صبر — رکھو — یہاں تک کہ اللہ فیصلہ کرے — وہ — بہترین — حاکم ہے۔
۳۔ عملی سبق: وحی کی پیروی اور صبر — کامیابی کی — چابی ہے۔"""
),
}
